namespace datagraph.data.graph;

using ghidra.graph.viewer.layout;
using ghidra.graph.viewer.layout;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * Provider for the DegLayout
 */
public class DegLayoutProvider : AbstractLayoutProvider<DegVertex, DegEdge, DataExplorationGraph> {
	private static readonly string NAME = "Data Graph Layout";

	private static readonly int VERTICAL_GAP = 50;
	private static readonly int HORIZONTAL_GAP = 100;

	/* @Override */
	public VisualGraphLayout<DegVertex, DegEdge> getLayout(DataExplorationGraph graph,
			TaskMonitor monitor)
    {
		DegLayout layout = new DegLayout(graph, VERTICAL_GAP, HORIZONTAL_GAP);
		initVertexLocations(graph, layout);
		return layout;
	}

	/* @Override */
	public string getLayoutName() {
		return NAME;
	}
}
